const d=-4,a=[{intervals:4,points:50},{intervals:3,points:30},{intervals:2,points:15},{intervals:1,points:5}];export const SACK=-5,INTERCEPTION=-10;export function pointsForPosition(t,o){for(const e of a)if(t>=-4+o*e.intervals)return e.points;return 0}export function ladderBands(t){const o=[...a].reverse().map(n=>({from:-4+t*n.intervals,points:n.points})),e=o.map((n,r)=>({from:n.from,to:r+1<o.length?o[r+1].from:1/0,points:n.points}));return[{from:-1/0,to:e[0].from,points:0},...e]}export function bandAt(t,o){const e=ladderBands(o);return e.find(n=>t>=n.from&&t<n.to)||e[0]}export function classifyPlay({ranWithBall:t,threwTo:o,ball:e,carrierX:n,lineInterval:r,reached50:u}){if(!t&&!o)return{result:"sack",points:SACK,headline:"Sacked",detail:"Nobody got the ball away in time."};if(!t){if(!e||!e.caught)return{result:"incomplete",points:0,headline:"Incomplete",detail:"The pass fell to the turf."};if(e.team!==0)return{result:"interception",points:INTERCEPTION,headline:"Intercepted",detail:"The Crows read it and took the ball away."};const s=pointsForPosition(n,r);return{result:"catch",points:s,headline:s===50?"All the way":"Caught",detail:s===50?"Caught and carried the whole way across.":`Caught and brought down for ${s}.`}}const i=pointsForPosition(n,r);return{result:u?"run-50":"run",points:i,headline:i===50?"All the way":"Kept it",detail:i===50?"Tucked it and ran the whole way across.":`Tucked it and ran for ${i}.`}}export function summarise(t){const o=t.reduce((n,r)=>n+r.points,0),e=t.reduce((n,r)=>r.points>n.points?r:n,t[0]||{points:0});return{total:o,plays:t.length,best:e?e.points:0,scored:t.filter(n=>n.points>0).length,gaveAway:t.filter(n=>n.points<0).length}}export function verdictFor(t){return t>=300?"A clinic.":t>=200?"A very good afternoon.":t>=120?"Solid work.":t>=60?"Moved the ball.":t>0?"Hard yards.":"One of those games."}
